from datetime import datetime

class Chat:
    TIMESTAMP_FORMAT = "%Y-%m-%d %H:%M:%S"

    def __init__(self):
        self.users = {}

    def _create_message_info(self, sender, receiver, message):
        timestamp = datetime.now().strftime(self.TIMESTAMP_FORMAT)
        return {
            'sender': sender,
            'receiver': receiver,
            'message': message,
            'timestamp': timestamp
        }

    def add_user(self, username):
        if username in self.users:
            return False
        self.users[username] = []
        return True

    def remove_user(self, username):
        if username in self.users:
            del self.users[username]
            return True
        return False

    def send_message(self, sender, receiver, message):
        if not self._validate_users(sender, receiver):
            return False

        message_info = self._create_message_info(sender, receiver, message)
        self.users[sender].append(message_info)
        self.users[receiver].append(message_info)
        return True

    def _validate_users(self, sender, receiver):
        return sender in self.users and receiver in self.users

    def get_messages(self, username):
        if username not in self.users:
            return []
        return self.users[username][:]
